gKq(){return"\u0647\u0630\u0627 \u0627\u0644\u0634\u062e\u0635 \u064a\u0628\u0644\u063a 15 \u0639\u0627\u0645\u064b\u0627 \u0623\u0648 \u0623\u0643\u062b\u0631 \u0648\u0647\u0648 \u0635\u0627\u062d\u0628 \u062d\u0633\u0627\u0628\u0647. \u0644\u0627 \u064a\u0645\u0643\u0646 \u0625\u0635\u062f\u0627\u0631 \u0631\u0645\u0632 \u062c\u062f\u064a\u062f \u0625\u0644\u0627 \u0625\u0630\u0627 \u0644\u0645 \u064a\u0628\u0642\u064e \u0644\u062f\u064a\u0647 \u0623\u064a \u062c\u0647\u0627\u0632 \u0646\u0634\u0637."},
gKp(){return"\u0644\u0646 \u064a\u064f\u0639\u0631\u0636 \u0647\u0630\u0627 \u0627\u0644\u0631\u0645\u0632 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u062f\u0648\u0651\u0646\u0647 \u0623\u0648 \u0627\u0646\u0633\u062e\u0647 \u0642\u0628\u0644 \u0627\u0644\u0625\u063a\u0644\u0627\u0642."},
gKm(){return"\u0647\u0627\u062a\u0641 \u0648\u0627\u062d\u062f \u0641\u0642\u0637 \u0641\u064a \u0643\u0644 \u0645\u0631\u0629: \u0628\u0645\u062c\u0631\u062f \u0627\u0633\u062a\u062e\u062f\u0627\u0645 \u0647\u0630\u0627 \u0627\u0644\u0631\u0645\u0632\u060c \u0633\u064a\u064f\u0641\u0635\u0644 \u0627\u0644\u062c\u0647\u0627\u0632 \u0627\u0644\u0633\u0627\u0628\u0642."},
gug(){return"\u0625\u0646\u0630\u0627\u0631 \u062c\u0627\u0631\u064d"},
CG(a){return"\u0623\u064f\u0637\u0644\u0642 \u0641\u064a "+a},
guf(){return"\u0633\u0623\u062a\u0648\u0644\u0649 \u0627\u0644\u0623\u0645\u0631"},
gCk(){return"\u0631\u0623\u064a\u062a \u0627\u0644\u0625\u0646\u0630\u0627\u0631"},
