z4(a,b){return"\u0623\u0646\u062a \u0639\u0644\u0649 \u0628\u064f\u0639\u062f "+a+" \u0645 \u0628\u0639\u062f \u0627\u0644\u062d\u062f\u0648\u062f \u2014 \u0641\u0648\u0642 \u0639\u062a\u0628\u0629 \u0627\u0644\u0625\u062b\u0628\u0627\u062a ("+b+" \u0645\u060c \u0628\u0645\u0627 \u064a\u0634\u0645\u0644 \u062f\u0642\u0629 \u0627\u0644\u0642\u064a\u0627\u0633): \u0633\u064a\u0628\u062f\u0623 \u0627\u0644\u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062a\u0644\u0642\u0627\u0626\u064a \u0647\u0646\u0627 (3 \u0642\u064a\u0627\u0633\u0627\u062a \u0628\u0641\u0627\u0635\u0644 ~10 \u062b\u0648\u0627\u0646\u064d)."},
z2(a,b){return"\u0623\u0646\u062a \u062e\u0627\u0631\u062c \u0627\u0644\u0645\u0646\u0637\u0642\u0629 ("+a+" \u0645 \u0628\u0639\u062f \u0627\u0644\u062d\u062f\u0648\u062f)\u060c \u0644\u0643\u0646 \u0647\u0630\u0627 \u0627\u0644\u0642\u064a\u0627\u0633 \u0644\u0627 \u064a\u0633\u062a\u0637\u064a\u0639 \u0625\u062b\u0628\u0627\u062a \u0630\u0644\u0643 \u0628\u0639\u062f: \u0628\u062f\u0642\u062a\u0647 \u0627\u0644\u062d\u0627\u0644\u064a\u0629 \u064a\u062c\u0628 \u062a\u062c\u0627\u0648\u0632 "+b+" \u0645. \u0627\u0628\u062a\u0639\u062f \u0623\u0643\u062b\u0631 \u0623\u0648 \u0627\u0646\u062a\u0638\u0631 \u0642\u064a\u0627\u0633\u064b\u0627 \u0623\u062f\u0642."},
