gxH(){return"\u0644\u0627 \u064a\u064f\u0643\u0634\u0641 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0633\u0631\u064a \u0627\u0644\u0637\u0648\u064a\u0644 \u0625\u0644\u0627 \u0644\u062d\u0638\u0629 \u0625\u0646\u0634\u0627\u0621 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062a\u0645\u0647\u064a\u062f\u064a\u060c \u0648\u0644\u0627 \u064a\u0645\u0643\u0646 \u0639\u0631\u0636\u0647 \u0645\u0631\u0629 \u0623\u062e\u0631\u0649. \u0631\u0645\u0632 \u0627\u0644\u0645\u0644\u0641 \u0623\u0639\u0644\u0627\u0647 \u0647\u0648 \u0645\u0627 \u062a\u0637\u0644\u0628\u0647 \u0642\u0648\u0627\u062a \u0627\u0644\u0623\u0645\u0646."},
gMc(){return"\u0623\u064f\u0631\u0633\u0644 \u0628\u0627\u0644\u0641\u0639\u0644 \u2014 \u0627\u0646\u0638\u0631 \u0627\u0644\u0645\u062a\u0627\u0628\u0639\u0629 \u0623\u062f\u0646\u0627\u0647."},
gyb(){return"\u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0645\u062a\u0648\u0642\u0641. \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17\u060c \u0623\u0648 \u0623\u0631\u0633\u0644\u0647 \u0625\u0644\u0649 \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649 \u0645\u0646 \u0627\u0644\u0628\u0637\u0627\u0642\u0629 \u0623\u062f\u0646\u0627\u0647."},
gE1(){return"\u0623\u064f\u0646\u0634\u0626 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062a\u0645\u0647\u064a\u062f\u064a \u0648\u0644\u0643\u0646\u0647 \u0644\u0645 \u064a\u064f\u0631\u0633\u0644"},
gE0(){return"\u0644\u0645 \u064a\u0635\u0644 \u0634\u064a\u0621 \u0628\u0639\u062f \u0625\u0644\u0649 \u0642\u0648\u0627\u062a \u0627\u0644\u0623\u0645\u0646. \u0623\u0631\u0633\u0644\u0647 \u0627\u0644\u0622\u0646\u060c \u0623\u0648 \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17 \u0648\u0623\u0639\u0637\u0647\u0645 \u0631\u0645\u0632 \u0627\u0644\u0645\u0644\u0641."},
gDX(){return"\u0627\u0644\u0625\u0631\u0633\u0627\u0644 \u0645\u062a\u0648\u0642\u0641"},
gDU(){return"\u0644\u0645 \u062a\u062a\u0633\u0644\u0645 \u0623\u064a \u0648\u062d\u062f\u0629 \u0647\u0630\u0627 \u0627\u0644\u0645\u0644\u0641 \u0627\u0644\u062a\u0645\u0647\u064a\u062f\u064a. \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17 \u0627\u0644\u0622\u0646 \u2014 \u0641\u0647\u0648 \u0627\u0644\u0633\u0628\u064a\u0644 \u0627\u0644\u0623\u0643\u064a\u062f \u0627\u0644\u0648\u062d\u064a\u062f."},
