gEm(){return"\u062c\u064f\u0631\u0650\u0651\u0628\u062a \u0645\u0646 \u0642\u0628\u0644 \u2014 \u062f\u0648\u0646 \u0631\u062f"},
guL(){return"\u0644\u0627 \u062a\u0648\u062c\u062f \u0648\u062d\u062f\u0629 \u0645\u062a\u0627\u062d\u0629 \u0641\u064a \u0627\u0644\u062f\u0644\u064a\u0644. \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17."},
LP(a){return"\u0623\u064f\u0631\u0633\u0644 \u0625\u0644\u0649 "+a+"."},
gGM(){return"\u0644\u0645 \u062a\u0639\u062f \u0645\u062a\u0635\u0644\u0627\u064b \u0628\u062d\u0633\u0627\u0628\u0643. \u064a\u064f\u0631\u062c\u0649 \u062a\u0633\u062c\u064a\u0644 \u0627\u0644\u062f\u062e\u0648\u0644 \u0645\u0646 \u062c\u062f\u064a\u062f."},
gGO(){return"\u0645\u062e\u0635\u0635 \u0644\u0623\u0634\u062e\u0627\u0635 \u0627\u0644\u062b\u0642\u0629 \u0644\u062f\u0649 \u0647\u0630\u0627 \u0627\u0644\u0634\u062e\u0635 \u0627\u0644\u0645\u062d\u0645\u064a."},
gGQ(){return"\u0647\u0630\u0647 \u0627\u0644\u0648\u062d\u062f\u0629 \u063a\u064a\u0631 \u0645\u062a\u0635\u0644\u0629 \u0628\u0640 Lyhanna. \u0627\u062e\u062a\u0631 \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649\u060c \u0623\u0648 \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17."},
gGP(){return"\u0644\u0627 \u064a\u0648\u062c\u062f \u0644\u062f\u0649 \u0647\u0630\u0647 \u0627\u0644\u0648\u062d\u062f\u0629 \u0623\u064a \u0645\u0633\u062a\u0644\u0645 \u064a\u0645\u0643\u0646 \u0627\u0644\u0648\u0635\u0648\u0644 \u0625\u0644\u064a\u0647. \u0627\u062e\u062a\u0631 \u0648\u062d\u062f\u0629 \u0623\u062e\u0631\u0649\u060c \u0623\u0648 \u0627\u062a\u0635\u0644 \u0628\u0627\u0644\u0631\u0642\u0645 17."},
