gGD(){return"\u062a\u0641\u0639\u064a\u0644 \u0627\u0644\u062d\u0645\u0627\u064a\u0629 \u062d\u0633\u0628 \u0627\u0644\u062c\u062f\u0648\u0644 \u0627\u0644\u0632\u0645\u0646\u064a"},
gGX(){return"\u0625\u062e\u0641\u0627\u0621 \u0645\u0646 \u0639\u0631\u0636\u064a"},
gw0(){return"\u0625\u0638\u0647\u0627\u0631 \u0645\u0646 \u062c\u062f\u064a\u062f"},
gr6(){return"\u0645\u062e\u0641\u064a"},
gvR(){return"\u0627\u0644\u0633\u062c\u0644"},
gGY(){return"\u0627\u0639\u062b\u0631 \u0639\u0644\u0649 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0627\u0644\u0633\u0627\u0628\u0642\u0629\u060c \u062d\u062a\u0649 \u0627\u0644\u0645\u062e\u0641\u064a\u0629 \u0645\u0646\u0647\u0627\u060c \u0628\u0627\u062e\u062a\u064a\u0627\u0631 \u0641\u062a\u0631\u0629 \u0632\u0645\u0646\u064a\u0629."},
